*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#203b3a;font-synthesis:none;font-optical-sizing:auto}body{margin:0;overflow:hidden;background:#d9ece6}button{font:inherit}#game{position:relative;width:100vw;height:100dvh;min-height:560px;overflow:hidden;background:linear-gradient(#c9e8e8,#e5efdc)}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(233,244,234,.9) 0%,rgba(233,244,234,.77) 23%,rgba(233,244,234,.24) 49%,transparent 73%),linear-gradient(0deg,rgba(27,62,50,.19),transparent 25%)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(38,81,69,.13);background:rgba(248,250,242,.48);backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#203b3a;font:700 14px 'Space Grotesk',sans-serif;letter-spacing:1.6px}.brand-icon{display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:#d5eee0;color:#398c68;font-size:20px}.brand-light{font-weight:500;opacity:.63;margin-left:4px}.location{position:absolute;left:50%;transform:translateX(-50%);font-size:10px;font-weight:800;letter-spacing:1.8px;color:#52716a;display:flex;align-items:center;gap:9px}.live-dot{width:7px;height:7px;border-radius:9px;background:#55b784;box-shadow:0 0 0 4px #55b78424}.wallet{display:flex;align-items:center;gap:8px;font:700 17px 'Space Grotesk',sans-serif}.coin{color:#d79542;font-size:17px}.coin-label{font:700 9px 'DM Sans';letter-spacing:1.3px;color:#788981;margin-left:1px}.left-rail{position:absolute;z-index:3;left:34px;top:50%;transform:translateY(-42%);display:flex;flex-direction:column;gap:10px}.rail-button{width:58px;height:58px;border:1px solid #ffffffaa;background:#f8faf2a8;border-radius:18px;color:#78918a;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;cursor:pointer;transition:.2s;backdrop-filter:blur(8px)}.rail-button>span{font-size:21px;line-height:24px}.rail-button small{font-size:8px;font-weight:700;letter-spacing:.2px}.rail-button:hover,.rail-button.active{background:#fff;color:#2c805e;box-shadow:0 7px 22px #244f3816;transform:translateX(2px)}.hud{position:absolute;z-index:2;left:clamp(115px,13vw,205px);top:clamp(105px,17vh,155px);width:min(370px,calc(100vw - 150px));pointer-events:none}.hud>*{pointer-events:auto}.intro .eyebrow,.eyebrow{font-size:9px;font-weight:800;letter-spacing:1.7px;color:#55826f}.sparkle{font-size:14px;color:#e3a34d;vertical-align:-1px;margin-right:5px}.intro h1{font:600 clamp(35px,4vw,48px)/1.07 'Space Grotesk',sans-serif;letter-spacing:-2.3px;margin:17px 0 10px;color:#23433e}.intro h1 em{font-style:normal;color:#42906a}.intro p{font-size:12px;line-height:1.7;color:#617770;margin:0;max-width:320px}.card{border:1px solid #ffffffc9;background:rgba(250,251,244,.9);box-shadow:0 14px 40px #264f3b12;backdrop-filter:blur(14px);border-radius:16px}.objective{margin-top:24px;padding:13px 15px;display:flex;align-items:center;gap:11px}.objective-icon{flex:0 0 34px;height:34px;border-radius:11px;background:#e4f2e8;display:grid;place-items:center;color:#43916a;font-size:21px}.objective-copy{display:grid;gap:3px;min-width:0}.objective-copy .eyebrow{font-size:8px;letter-spacing:1.2px}.objective-copy strong{font-size:11px;color:#345148}.objective-copy>span:last-child{font-size:9px;color:#82948a}.mission-reward{white-space:nowrap;margin-left:auto;font:700 11px 'Space Grotesk';color:#b27a2d}.action-card{margin-top:11px;padding:17px 17px 13px}.action-head{display:flex;align-items:center;justify-content:space-between}.action-head h2{font:600 19px 'Space Grotesk';letter-spacing:-.5px;margin:4px 0 0}.wind{font-size:12px;color:#61a27a}.wind span{font-size:8px;font-weight:800;letter-spacing:.7px;color:#80958b}.rocket-status{display:flex;align-items:center;gap:10px;padding:12px 0 10px;border-bottom:1px solid #e8eee6}.rocket-thumb{width:40px;height:40px;border-radius:12px;background:#e6f1e7;display:grid;place-items:center}.rocket-emoji{font-size:23px;filter:saturate(.6)}.rocket-info{display:grid;gap:3px}.rocket-info strong{font-size:11px}.rocket-info span{font-size:9px;color:#819087}.ready-tag{margin-left:auto;font-size:8px;font-weight:800;letter-spacing:.7px;color:#438862;padding:5px 7px;border-radius:6px;background:#e4f3e7}.fuel-row{padding-top:12px}.fuel-label{display:flex;justify-content:space-between;align-items:center;font-size:8px;font-weight:800;letter-spacing:1px;color:#748a80}.fuel-label strong{font:700 11px 'Space Grotesk';color:#36845f}.meter{height:7px;margin-top:8px;background:#e8eee5;border-radius:8px;position:relative;overflow:hidden}.meter-fill{height:100%;width:0;background:linear-gradient(90deg,#7cc891,#44a96b);border-radius:8px;transition:width .18s}.meter-tick{position:absolute;top:0;bottom:0;width:2px;background:#f8faf4;left:25%}.meter-tick:nth-child(3){left:50%}.meter-tick:nth-child(4){left:75%}.action-buttons{display:grid;grid-template-columns:1fr 1.4fr;gap:8px;margin-top:13px}.action-buttons button{height:39px;border-radius:10px;border:0;display:flex;align-items:center;justify-content:center;gap:6px;font-size:9px;font-weight:800;letter-spacing:.8px;cursor:pointer;transition:.16s}.action-buttons button:active{transform:scale(.97)}.secondary-button{background:#edf3eb;color:#507165}.secondary-button:hover{background:#e2eee2}.pump-icon{font-size:15px}.action-buttons kbd{font:700 8px 'DM Sans';padding:3px 4px;border-radius:4px;background:#fff;color:#84958c}.primary-button{background:#438e68;color:white;box-shadow:0 5px 12px #438e6830}.primary-button:hover{background:#317b56}.button-arrow{font-size:14px;margin-left:2px}.action-hint{margin-top:10px;text-align:center;color:#8a9b91;font-size:9px}.bottom-hint{position:absolute;left:0;right:0;bottom:20px;display:flex;align-items:center;justify-content:center;gap:9px;color:#526e63;font-size:8px;font-weight:800;letter-spacing:1.1px}.hint-key{border:1px solid #ffffffbd;border-radius:5px;padding:5px 7px;background:#f7f9f0a8;letter-spacing:2px}.hint-divider{opacity:.5}.mouse-icon{font-size:14px}.scene-label{position:absolute;right:clamp(30px,8vw,130px);bottom:14%;display:flex;align-items:center;gap:9px;color:#f5fff0;text-shadow:0 1px 5px #254d39;font-size:9px;font-weight:800;letter-spacing:1.4px;pointer-events:none}.label-line{width:30px;height:1px;background:#f5fff0}.toast{position:absolute;z-index:8;top:90px;left:50%;transform:translate(-50%,-12px);padding:11px 17px;background:#264a3c;color:white;border-radius:10px;font-size:12px;font-weight:700;opacity:0;transition:.25s;pointer-events:none;box-shadow:0 10px 24px #1f463945}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:absolute;z-index:10;inset:0;background:#17382d61;backdrop-filter:blur(5px);display:none;align-items:center;justify-content:center;padding:20px}.modal-backdrop.open{display:flex}.modal{position:relative;width:min(560px,100%);max-height:min(700px,90vh);overflow:auto;background:#f8faf2;border:1px solid #ffffff;border-radius:22px;padding:28px;box-shadow:0 28px 80px #17382d55;animation:modal-in .22s ease-out}@keyframes modal-in{from{opacity:0;transform:translateY(12px) scale(.98)}to{opacity:1;transform:none}}.close-modal{position:absolute;right:17px;top:15px;width:32px;height:32px;border:0;border-radius:10px;background:#eaf0e8;color:#557066;font-size:22px;cursor:pointer}.modal-kicker{font-size:9px;letter-spacing:1.7px;font-weight:800;color:#55906d}.modal h2{font:600 29px 'Space Grotesk';letter-spacing:-1px;margin:6px 0 5px;color:#28483d}.modal-desc{font-size:12px;color:#72867c;margin:0 0 20px;line-height:1.6}.shop-tabs{display:flex;gap:7px;margin-bottom:15px}.shop-tab{border:0;border-radius:8px;padding:8px 12px;background:#edf2e9;color:#647c70;font-size:10px;font-weight:700;cursor:pointer}.shop-tab.active{background:#3f8b64;color:white}.item-list{display:grid;gap:9px}.shop-item{padding:13px;border:1px solid #e7ece3;background:#fffefa;border-radius:13px;display:flex;align-items:center;gap:12px}.item-art{width:47px;height:47px;border-radius:12px;background:#eaf3e9;display:grid;place-items:center;font-size:25px;flex-shrink:0}.item-copy{min-width:0;flex:1}.item-copy strong{font-size:12px;display:block}.item-copy p{font-size:9px;color:#829187;line-height:1.45;margin:4px 0 0}.item-buy{border:0;border-radius:8px;background:#478e67;color:#fff;padding:9px 11px;font-size:10px;font-weight:800;white-space:nowrap;cursor:pointer}.item-buy:hover{background:#31784f}.item-buy:disabled{background:#e8eee5;color:#829187;cursor:default}.item-buy.equipped{background:#e5f2e7;color:#42825c}.stat-pills{display:flex;gap:6px;margin-top:7px}.stat-pills span{font-size:8px;color:#55806b;background:#edf5ed;border-radius:4px;padding:3px 5px}.mission-list{display:grid;gap:10px}.mission-row{display:flex;align-items:center;gap:12px;padding:13px;border:1px solid #e7ece3;border-radius:12px;background:#fffefa}.mission-check{width:29px;height:29px;border-radius:9px;display:grid;place-items:center;background:#e7f2e7;color:#498860;font-weight:800}.mission-row div:nth-child(2){flex:1}.mission-row strong{font-size:11px;display:block}.mission-row small{color:#829187;font-size:9px}.mission-coins{font-size:10px;color:#b27a2d;font-weight:800}.launch-overlay{position:absolute;z-index:9;inset:0;display:none;align-items:flex-start;justify-content:center;padding-top:100px;background:linear-gradient(180deg,#24483725,transparent 58%);pointer-events:none}.launch-overlay.show{display:flex}.launch-caption{text-align:center;color:#fff;text-shadow:0 3px 20px #173a28}.launch-caption span{font-size:10px;letter-spacing:3px;font-weight:800;display:block}.launch-caption strong{font:700 58px 'Space Grotesk';display:block;letter-spacing:-3px}.launch-caption small{font-size:9px;font-weight:700;letter-spacing:1.5px}.result-card{margin-top:16px;padding:14px;border-radius:12px;background:#eaf3e8;display:flex;justify-content:space-between;align-items:center}.result-card strong{font:700 20px 'Space Grotesk';color:#37815a}.result-card span{font-size:10px;color:#6b8275}.modal-action{margin-top:14px;width:100%;border:0;border-radius:10px;padding:12px;background:#438e68;color:#fff;font-size:11px;font-weight:800;cursor:pointer}.mobile-controls{display:none}
@media(max-width:700px){#game{min-height:500px}.topbar{height:58px;padding:0 16px}.brand{font-size:11px;gap:7px}.brand-icon{width:29px;height:29px}.location{display:none}.wallet{font-size:15px}.left-rail{left:10px;top:auto;bottom:77px;transform:none;gap:7px}.rail-button{width:46px;height:46px;border-radius:14px}.rail-button>span{font-size:18px;line-height:19px}.rail-button small{font-size:7px}.hud{left:68px;top:76px;width:min(330px,calc(100vw - 82px))}.intro h1{font-size:33px;letter-spacing:-1.6px;margin:10px 0 5px}.intro .eyebrow{font-size:8px}.intro p{font-size:10px;line-height:1.5;max-width:250px}.objective{margin-top:12px;padding:9px 10px;gap:8px}.objective-icon{flex-basis:29px;height:29px}.objective-copy strong{font-size:9px}.objective-copy>span:last-child{font-size:8px}.mission-reward{font-size:9px}.action-card{margin-top:8px;padding:12px}.action-head h2{font-size:16px}.action-head .eyebrow{font-size:8px}.wind span{font-size:7px}.rocket-status{padding:9px 0 8px}.rocket-thumb{width:34px;height:34px}.rocket-emoji{font-size:19px}.rocket-info strong{font-size:10px}.rocket-info span{font-size:8px}.fuel-row{padding-top:9px}.action-buttons{margin-top:10px}.action-buttons button{height:36px;font-size:8px}.action-hint{font-size:8px;margin-top:7px}.bottom-hint{bottom:14px;left:58px;font-size:7px;gap:6px}.scene-label{right:12px;bottom:29%;font-size:7px}.scene-label .label-line{width:17px}.vignette{background:linear-gradient(90deg,rgba(233,244,234,.91) 0%,rgba(233,244,234,.74) 57%,rgba(233,244,234,.12) 100%),linear-gradient(0deg,rgba(27,62,50,.25),transparent 27%)}.modal{padding:23px 17px 17px;border-radius:18px}.modal h2{font-size:25px}.launch-overlay{padding-top:80px}.launch-caption strong{font-size:47px}}
@media(max-height:700px) and (min-width:701px){.hud{top:95px}.intro h1{font-size:39px;margin:11px 0 6px}.objective{margin-top:14px}.bottom-hint{bottom:12px}}

import * as THREE from 'three';
import './style.css';

const $ = (s) => document.querySelector(s);
const scene = new THREE.Scene();
scene.background = new THREE.Color('#c9e8e8');
scene.fog = new THREE.Fog('#c9e8e8', 23, 58);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 100);
camera.position.set(0, 2.1, 10.5);
const renderer = new THREE.WebGLRenderer({ canvas: $('#scene'), antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
scene.add(new THREE.HemisphereLight('#e9fbff', '#768b61', 2.15));
const sun = new THREE.DirectionalLight('#fff1ce', 3.2); sun.position.set(-7, 12, 8); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -18; sun.shadow.camera.right = 18; sun.shadow.camera.top = 18; sun.shadow.camera.bottom = -18; scene.add(sun);
const mat = (color, roughness=.85) => new THREE.MeshStandardMaterial({ color, roughness });
const mats = {
  grass:mat('#83b884'), grass2:mat('#93c68d'), cream:mat('#f2dfbe'), wall:mat('#ead8b9'), roof:mat('#bd7860'), roof2:mat('#d38c68'), wood:mat('#946c48'), darkwood:mat('#654e39'), white:mat('#fff5dd'), glass: new THREE.MeshStandardMaterial({color:'#8cc8cb',roughness:.27,metalness:.1}), trim:mat('#fff4dd'), stone:mat('#d8d1b5'), path:mat('#baad8e'), leaf:mat('#608c60'), leaf2:mat('#82aa68'), trunk:mat('#806047'), metal:mat('#647f7a',.42), shadow:mat('#385c4c'), red:mat('#db755a'), yellow:mat('#f1c96e')
};
function box(parent, name, size, pos, material, cast=true) {const o=new THREE.Mesh(new THREE.BoxGeometry(...size), material);o.name=name;o.position.set(...pos);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o;}
function sphere(parent,size,pos,material,scale=[1,1,1]){const o=new THREE.Mesh(new THREE.SphereGeometry(size,18,14),material);o.position.set(...pos);o.scale.set(...scale);o.castShadow=true;parent.add(o);return o;}
function cylinder(parent,r1,r2,h,pos,material,segments=16){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);o.position.set(...pos);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function cone(parent,r,h,pos,material){return cylinder(parent,0,r,h,pos,material,12);}
// Soft, storybook neighborhood and garden
box(scene,'Lawn',[80,.22,80],[0,-.17,-16],mats.grass,false);
box(scene,'Flowerbed',[18,.12,7],[-13,-.04,-6],mats.grass2,false);
// House with a visible garage/workshop on the right
box(scene,'House',[8,4.2,4.3],[2.5,2.1,-6],mats.wall);
const roofL=box(scene,'Roof',[4.8,.22,5], [0,4.48,-6],mats.roof);roofL.rotation.z=-.48;
const roofR=box(scene,'Roof',[4.8,.22,5], [5,4.48,-6],mats.roof2);roofR.rotation.z=.48;
box(scene,'Eave',[8.35,.2,.3],[2.5,3.98,-3.78],mats.trim);
box(scene,'Door',[1.2,2.25,.16],[2.25,1.17,-3.78],mats.wood);
sphere(scene,.055,[2.67,1.22,-3.65],mats.yellow);
for(const x of [-.15,4.95]){box(scene,'Window',[1.3,1.3,.14],[x,2.45,-3.74],mats.glass);box(scene,'Window trim',[1.48,.1,.18],[x,2.45,-3.64],mats.trim);box(scene,'Window trim',[.1,1.48,.18],[x,2.45,-3.64],mats.trim);box(scene,'Window mullion',[.06,1.25,.2],[x,2.45,-3.62],mats.trim);box(scene,'Window mullion',[1.25,.06,.2],[x,2.45,-3.62],mats.trim)}
// Garage extension and open door
box(scene,'Garage',[5.5,3.5,5],[8.8,1.75,-5.7],mats.cream);
box(scene,'Garage roof',[5.9,.26,5.4],[8.8,3.55,-5.65],mats.roof);
box(scene,'Garage interior',[4.4,2.85,.13],[8.8,1.52,-3.12],mats.shadow);
box(scene,'Workbench',[2.7,.18,.9],[8.8,.9,-4.65],mats.wood);
for(const x of [7.65,9.95])box(scene,'Bench legs',[.13,.85,.13],[x,.44,-4.35],mats.darkwood);
box(scene,'Pegboard',[2.8,1.35,.13],[8.8,2.4,-3.28],mat('#c6ad88'));
// workshop shelf and colorful tools
box(scene,'Shelf',[.75,2,.75],[6.35,1.3,-4.3],mats.wood);
for(let i=0;i<3;i++)box(scene,'Shelf boards',[.8,.08,.8],[6.35,.62+i*.62,-4.3],mats.darkwood);
const toolColors=['#edbd5b','#68a5a0','#d77c5e','#f3e3bf'];
for(let i=0;i<4;i++){cylinder(scene,.07,.07,.48,[7.8+i*.56,1.45,-3.35],mat(toolColors[i]),10)}
// stone walkway, launch site and striped landing pad
box(scene,'Walkway',[2.3,.12,10],[3.1,-.005,1.9],mats.path,false);
box(scene,'Pad base',[2,.14,2],[1.2,.09,-.25],mats.stone);
const pad = new THREE.Mesh(new THREE.CylinderGeometry(.66,.8,.24,16),mats.metal);pad.position.set(1.2,.26,-.25);pad.castShadow=true;scene.add(pad);
cylinder(scene,.07,.1,.53,[1.2,.62,-.25],mats.white,12);
// Water-bottle rocket group with selectable paint and proper fins/nozzle
const rocket = new THREE.Group();scene.add(rocket);rocket.position.set(1.2,.91,-.25);
let rocketBody, rocketNose, rocketFinMat;
function makeRocket(color='#55a895'){
  if(rocketBody)rocket.remove(rocketBody);
  const body=new THREE.Group();rocket.add(body);
  const bodyMat=mat(color,.35), capMat=mat('#f5ead4',.32);
  const bodyMesh=cylinder(body,.205,.205,.91,[0,.72,0],bodyMat,20);bodyMesh.name='Bottle';
  cylinder(body,.208,.205,.11,[0,.21,0],mats.metal,20);
  const nose=cone(body,.205,.44,[0,1.395,0],mat('#f2c46d',.38));
  cylinder(body,.22,.22,.07,[0,1.22,0],capMat,20);
  const fins=mat('#e47e5f');rocketFinMat=fins;
  for(let i=0;i<3;i++){const f=box(body,'Fin',[.11,.36,.33],[0,.4,.19],fins);f.rotation.z=-.2;f.rotation.y=i*Math.PI*2/3}
  cylinder(body,.12,.17,.13,[0,.18,0],mats.white,16);
  const stripe=cylinder(body,.207,.207,.055,[0,.88,0],mat('#fff2d6',.4),20);stripe.name='Bottle label';
  rocketBody=body;
}
makeRocket();
// Launch pump, hose, gauge and a small garden launch flag
const pumpGroup=new THREE.Group();scene.add(pumpGroup);pumpGroup.position.set(2.4,0,-.28);
box(pumpGroup,'Pump base',[.43,.12,.43],[0,.12,0],mats.red);
cylinder(pumpGroup,.12,.14,.95,[0,.65,0],mats.metal,16);
cylinder(pumpGroup,.065,.065,.11,[0,1.15,0],mats.yellow,16);
box(pumpGroup,'Handle',[.57,.08,.11],[0,1.2,0],mats.red);
const hose=new THREE.Mesh(new THREE.TorusGeometry(.24,.025,8,24,Math.PI),mat('#354f4c'));hose.position.set(-.2,.52,0);hose.rotation.z=Math.PI;hose.rotation.x=Math.PI/2;pumpGroup.add(hose);
const flag=box(scene,'Launch flag',[.06,1,.06],[.32,.56,-.2],mats.darkwood);box(scene,'Flag',[.47,.28,.05],[.57,.93,-.2],mats.red);
// Clouds, trees, bushes, flowers, stepping stones and distant fence
function tree(x,z,s=1){cylinder(scene,.19*s,.3*s,1.5*s,[x,.66*s,z],mats.trunk,9);sphere(scene,.75*s,[x,.66+1.12*s,z],mats.leaf,[1,1.08,1]);sphere(scene,.52*s,[x-.35*s,.78+1.2*s,z+.12*s],mats.leaf2);sphere(scene,.48*s,[x+.38*s,.75+1.3*s,z-.12*s],mats.leaf)}
for(const [x,z,s] of [[-7,-3,1.5],[-10,-10,1.9],[13,-7,1.8],[11,1,1.2],[-7,3,1]])tree(x,z,s);
for(let i=0;i<8;i++){const x=-5+(i%4)*4,z=-9-Math.floor(i/4)*.3;box(scene,'Fence post',[.13,.8,.13],[x,.4,z],mats.trim);if(i<7)box(scene,'Fence rail',[3.8,.09,.08],[x+1.85,.58,z],mats.trim)}
